"""The starter live show (native/live_show.py): its Show bank whole on its grid, the deck pads, the clip and camera
pads on deck C, the camera picked without the phone, the clip made when ffmpeg is here.

    python tests/test_live_show.py
"""
# AI: below section was generated by an AI
import os
import shutil
import sys
import tempfile
from types import SimpleNamespace

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from native import live_show as L, pads, video, vj  # noqa: E402

failed = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        failed.append(what)


st = {"next_id": 1, "banks": []}
st["banks"] = [pads.starter(st), L.show_bank(st)]
b = st["banks"][1]
n = len(b["controls"])
kept = pads.state(SimpleNamespace(options={"pads": st}))
show = next(x for x in kept["banks"] if x["name"] == "Show")
check(len(show["controls"]) == n == 10, f"every control of the Show bank kept on its grid ({len(show['controls'])} of {n})")
cells = [(c["x"] + i, c["y"] + j) for c in show["controls"] for i in range(c["w"]) for j in range(c["h"])]
check(len(cells) == len(set(cells)) == 16, "the bank's 4 x 4 cells each taken once")
kinds = {c["target"].get("kind") for c in show["controls"]}
check({"vj_sel_a", "vj_sel_b", "vj_sel_c", "vj_sel_next", "pad_clip", "pad_cam"} <= kinds, f"deck pads, a clip, a camera ({kinds})")
check(all(c["target"]["deck"] == 2 for c in show["controls"] if c["target"].get("kind") in ("pad_clip", "pad_cam")),
      "the clip and the camera on deck C")
check(all(c["target"].get("deck") == vj.SEL for c in show["controls"] if c["type"] == "knob"), "the knobs on the selected deck")
ids = [c["id"] for bank in kept["banks"] for c in bank["controls"]]
check(len(ids) == len(set(ids)), "ids unique across both banks")
check(L.first_camera(["Integrated Camera", video.PHONE]) == "Integrated Camera" and L.first_camera([video.PHONE]) is None,
      "the camera: the first webcam, never the phone")
check(all(look in __import__("native.vj_looks", fromlist=["v"]).LOOKS for look in L.LOOKS), f"the decks' looks exist ({L.LOOKS})")
if video.ffmpeg():
    d = tempfile.mkdtemp()
    try:
        got = L.make_clip(os.path.join(d, *vj.MEDIA_DIR.split("/")))
        f = os.path.join(d, *got.split("/")) if got else ""
        check(got == f"{vj.MEDIA_DIR}/{L.CLIP_FILE}" and os.path.getsize(f) > 10000, f"the clip made by ffmpeg ({got})")
    finally:
        shutil.rmtree(d, ignore_errors=True)
else:
    check(L.make_clip(tempfile.mkdtemp()) is None, "no ffmpeg: no clip, and no error")
print("FAILED:", failed) if failed else print("all ok")
sys.exit(1 if failed else 0)
# AI: end
